import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${select({id: "cvScenario",label: "Content type",value: "articles",options: [{ label: "Article list / blog feed", value: "articles" },{ label: "Card grid (products, posts)", value: "cards" },{ label: "Documentation sections", value: "docs" },{ label: "Comment thread", value: "comments" },{ label: "Custom", value: "custom" }]})}${field({ id: "cvHeight", label: "Estimated height px", value: "400", type: "number", help: "contain-intrinsic-size. Use a value close to the average content height." })}${field({ id: "cvSelector", label: "Selector", value: ".content-section", full: true })}</div>`,generate(root) {const scenario = root.querySelector("#cvScenario").value;const height = root.querySelector("#cvHeight").value || "400";const selector = root.querySelector("#cvSelector").value.trim() || ".content-section";const defaults = { articles: "300", cards: "350", docs: "500", comments: "200", custom: height };const h = defaults[scenario];return { output: `${selector} {content-visibility: auto;contain-intrinsic-size: auto ${h}px;}/* How it works:content-visibility: auto skips rendering for off-screen content.contain-intrinsic-size gives the browser an estimated height so thescrollbar stays stable before the section is rendered.When the section approaches the viewport, the browser renders it fully.Browser support: Chrome 85+, Edge 85+, Firefox 125+, Safari 18.2+ */` };}};